We're on Go 1.27. This generic container library grew organically and the package-level helper functions are awkward to discover. Improve the API ergonomics.

```go
package set

type Set[T comparable] struct {
    items map[T]struct{}
}

func New[T comparable](items ...T) *Set[T] {
    s := &Set[T]{items: make(map[T]struct{}, len(items))}
    for _, it := range items {
        s.items[it] = struct{}{}
    }
    return s
}

func (s *Set[T]) Add(v T) { s.items[v] = struct{}{} }

func (s *Set[T]) Contains(v T) bool { _, ok := s.items[v]; return ok }

func (s *Set[T]) ForEach(f func(T)) {
    for v := range s.items {
        f(v)
    }
}

// MapSet applies f to every element and returns a new set.
func MapSet[T comparable, U comparable](s *Set[T], f func(T) U) *Set[U] {
    out := New[U]()
    s.ForEach(func(v T) { out.Add(f(v)) })
    return out
}

// FilterSet returns the elements of s for which keep returns true.
func FilterSet[T comparable](s *Set[T], keep func(T) bool) *Set[T] {
    out := New[T]()
    s.ForEach(func(v T) {
        if keep(v) {
            out.Add(v)
        }
    })
    return out
}

type Iteratable[T comparable] interface {
    ForEach(f func(T))
}

var _ Iteratable[int] = (*Set[int])(nil)
